//! Running comparator networks on a block of vectors.
//!
//! Small stacks (n up to `Vector::UNROLL`) run a straight-line network generated by
//! `build.rs`, so every wire lives in a register. Deeper stacks sort aligned chunks with the
//! same register-resident networks and then run the remaining (rank-pruned) Batcher merge
//! levels from a comparator list over an L1-resident buffer.

use crate::netgen::{self, Comparator};
use crate::simd::Vector;
use std::collections::HashMap;
use std::sync::{Arc, Mutex, OnceLock};

include!(concat!(env!("OUT_DIR"), "/unrolled.rs"));

#[derive(Debug, Clone)]
pub enum NetPlan {
    /// n <= 1: nothing to do.
    Trivial,
    /// Straight-line network; `kind` 0 = full sort, 1 = median-pruned.
    Unrolled { n: usize, kind: u8 },
    /// Unrolled sorts of aligned `chunk`-wide blocks, then interpreted merge levels.
    Hybrid { n: usize, chunk: usize, suffix: Arc<Vec<Comparator>> },
    /// Interpreted comparator list.
    Interp(Arc<Vec<Comparator>>),
}

impl NetPlan {
    /// Comparators this plan executes (for reporting).
    pub fn comparators(&self) -> usize {
        match self {
            NetPlan::Trivial => 0,
            NetPlan::Unrolled { n, kind } => {
                let full = netgen::batcher(*n);
                if *kind == 0 {
                    full.len()
                } else {
                    netgen::prune(&full, *n, &netgen::median_ranks(*n)).len()
                }
            }
            NetPlan::Hybrid { n, chunk, suffix } => {
                let mut c = 0;
                let mut s = 0;
                while s < *n {
                    let w = (*n - s).min(*chunk);
                    c += netgen::batcher(w).len();
                    s += w;
                }
                c + suffix.len()
            }
            NetPlan::Interp(v) => v.len(),
        }
    }
}

type Key = (usize, Vec<usize>);
fn cache() -> &'static Mutex<HashMap<Key, Arc<(Vec<Comparator>, Vec<u32>)>>> {
    static C: OnceLock<Mutex<HashMap<Key, Arc<(Vec<Comparator>, Vec<u32>)>>>> = OnceLock::new();
    C.get_or_init(|| Mutex::new(HashMap::new()))
}

/// Batcher network for `n` wires pruned to `needed` (all wires when `None`), with levels.
fn pruned_with_levels(n: usize, needed: Option<&[usize]>) -> Arc<(Vec<Comparator>, Vec<u32>)> {
    let mut key_r: Vec<usize> = needed.map(|r| r.to_vec()).unwrap_or_default();
    key_r.sort_unstable();
    key_r.dedup();
    let key = (n, if needed.is_some() { key_r.clone() } else { vec![usize::MAX] });
    if let Some(v) = cache().lock().unwrap().get(&key) {
        return v.clone();
    }
    let (full, lv) = netgen::batcher_levels(n);
    let v = match needed {
        None => (full, lv),
        Some(_) => {
            // prune while keeping the level tags aligned
            let mut live = vec![false; n];
            for &k in &key_r {
                if k < n {
                    live[k] = true;
                }
            }
            let mut keep = Vec::new();
            for (i, &(a, b)) in full.iter().enumerate().rev() {
                if live[a as usize] || live[b as usize] {
                    live[a as usize] = true;
                    live[b as usize] = true;
                    keep.push(i);
                }
            }
            keep.reverse();
            (keep.iter().map(|&i| full[i]).collect(), keep.iter().map(|&i| lv[i]).collect())
        }
    };
    let v = Arc::new(v);
    let mut c = cache().lock().unwrap();
    if c.len() > 256 {
        c.clear();
    }
    c.insert(key, v.clone());
    v
}

/// Pick the fastest way to deliver ranks `needed` (`None` = a full sort) of `n` wires, given
/// that stacks up to `unroll` wires fit the unrolled networks.
pub fn plan(n: usize, needed: Option<&[usize]>, unroll: usize) -> NetPlan {
    if n <= 1 {
        return NetPlan::Trivial;
    }
    let is_median = needed.map(|r| {
        let mut r = r.to_vec();
        r.sort_unstable();
        r.dedup();
        r == netgen::median_ranks(n)
    });
    let pr = pruned_with_levels(n, needed);
    if n <= unroll.min(MAX_UNROLL) {
        let kind = if is_median == Some(true) { 1 } else { 0 };
        if kind == 0 && needed.is_some() {
            // A tiny rank set (say, the minimum) can be far cheaper interpreted.
            let full = netgen::batcher(n).len();
            if pr.0.len() * 3 < full {
                return NetPlan::Interp(Arc::new(pr.0.clone()));
            }
        }
        return NetPlan::Unrolled { n, kind };
    }
    let mut chunk = 1;
    while chunk * 2 <= unroll.min(MAX_UNROLL) {
        chunk *= 2;
    }
    if chunk >= 8 {
        let suffix: Vec<Comparator> = pr
            .0
            .iter()
            .zip(pr.1.iter())
            .filter(|(_, &l)| l as usize >= chunk)
            .map(|(&c, _)| c)
            .collect();
        return NetPlan::Hybrid { n, chunk, suffix: Arc::new(suffix) };
    }
    NetPlan::Interp(Arc::new(pr.0.clone()))
}

/// Interpreted bitonic merger for `n` wires (valley-shaped input).
pub fn bitonic_plan(n: usize) -> NetPlan {
    if n <= 1 {
        NetPlan::Trivial
    } else {
        NetPlan::Interp(Arc::new(netgen::bitonic_merge(n)))
    }
}

#[inline(always)]
unsafe fn interp<V: Vector>(b: *mut V, net: &[Comparator]) {
    for &(i, j) in net {
        let x = *b.add(i as usize);
        let y = *b.add(j as usize);
        *b.add(i as usize) = x.min(y);
        *b.add(j as usize) = x.max(y);
    }
}

/// Run `plan` on the `n` vectors at `b`.
#[inline(always)]
pub unsafe fn apply<V: Vector>(b: *mut V, plan: &NetPlan) {
    match plan {
        NetPlan::Trivial => {}
        NetPlan::Unrolled { n, kind } => {
            if V::UNROLL > 0 {
                unrolled::<V>(b, *n, *kind)
            }
        }
        NetPlan::Hybrid { n, chunk, suffix } => {
            if V::UNROLL > 0 {
                let mut s = 0;
                while s < *n {
                    let w = (*n - s).min(*chunk);
                    unrolled::<V>(b.add(s), w, 0);
                    s += w;
                }
            }
            interp(b, suffix);
        }
        NetPlan::Interp(net) => interp(b, net),
    }
}
